private void Rap_MagazinaEcuriaHyrjeve_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	 	DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldDealer = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("dealer", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldDealer.FieldName = "dealer";
            fieldDealer.Caption = "Dealer";

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldDyqani = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("dyqani", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldDyqani.FieldName = "dyqani";
            fieldDyqani.Caption = "Dyqani";

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldKartela = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("kartela", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldKartela.FieldName = "kartela";
            fieldKartela.Caption = "Kartela";
            fieldKartela.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldPershkrimi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("pershkrimi", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldPershkrimi.FieldName = "pershkrimi";
            fieldPershkrimi.Caption = "Pershkrimi";
            fieldPershkrimi.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldKategoria = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("kategoria", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldKategoria.FieldName = "kategoria";
            fieldKategoria.Caption = "Kategoria";
            fieldKategoria.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldNenKategoria = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("nenkategoria", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldNenKategoria.FieldName = "nenkategoria";
            fieldNenKategoria.Caption = "Nenkategoria";
            fieldNenKategoria.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldJava = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("data", DevExpress.XtraPivotGrid.PivotArea.ColumnArea);
            fieldJava.FieldName = "data";
            fieldJava.Caption = "Java";

		DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldVleraSasi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("sasia", DevExpress.XtraPivotGrid.PivotArea.DataArea);
            fieldVleraSasi.FieldName = "sasia";
            fieldVleraSasi.Caption = "Sasia";


		hyrjePivotGrid.Fields.Clear();
            hyrjePivotGrid.Fields.AddRange(new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField[] { fieldDealer, fieldDyqani, fieldKartela, fieldPershkrimi, fieldKategoria, fieldNenKategoria, fieldJava, fieldVleraSasi });
            fieldJava.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;
            fieldVleraSasi.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;
            hyrjePivotGrid.Styles.FieldHeaderStyle = hyrjePivotGrid.Styles.FieldHeaderStyle;
            hyrjePivotGrid.Styles.FieldValueStyle = hyrjePivotGrid.Styles.FieldHeaderStyle;
            hyrjePivotGrid.FieldValueGrandTotalStyleName = hyrjePivotGrid.Styles.FieldHeaderStyle.Name;
            this.PrintingSystem.Document.AutoFitToPagesWidth = 1;
}

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);


}

private void hyrjePivotGrid_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            hyrjePivotGrid.BestFit();
 		hyrjePivotGrid.CanGrow = true;
 		hyrjePivotGrid.CanShrink = true;

        }

private void hyrjePivotGrid_CustomFieldValueCells(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotCustomFieldValueCellsEventArgs e)
        {
            if (hyrjePivotGrid.RowCount == 1 && hyrjePivotGrid.ColumnCount == 1)
                return;
            for (int i = 0; i < hyrjePivotGrid.RowCount; i++)
            {

                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell0 = e.GetCell(false, 0);
                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell1 = e.GetCell(false, 1);
                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell2 = e.GetCell(false, 2);
                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell3 = e.GetCell(false, 3);
                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell4 = e.GetCell(false, 4);
                DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell5 = e.GetCell(false, 5);

                if (cell0 == null || cell1 == null || cell2 == null || cell3 == null || cell4 == null || cell5 == null) continue;
                if ((cell0.DisplayText == "") && (cell1.DisplayText == "") && (cell2.DisplayText == "") && (cell3.DisplayText == "") && (cell4.DisplayText == "") &&
                    (cell5.DisplayText == ""))
                    e.Remove(cell0);
            }
	}
private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	AlphaWebReports.raporteUtil.shtoFiltra((XRTable)sender, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}
